from solution import display_width
import unicodedata


def test_empty():
    assert display_width('') == 0


def test_ascii():
    assert display_width('abc') == 3


def test_hangul():
    assert display_width('한국') == 4


def test_fullwidth_letters():
    assert display_width('ＡＢ') == 4


def test_combining_mn():
    assert display_width('e\u0301') == 1


def test_combining_me():
    assert display_width('a\u20dd') == 1


def test_zwj():
    assert display_width('a\u200db') == 2


def test_emoji_wide():
    assert display_width('😀') == 2


def test_emoji_zwj_sequence():
    # 👨 ZWJ 👩 : 2 + 0 + 2
    assert display_width('👨\u200d👩') == 4


def test_halfwidth_katakana_is_one():
    assert display_width('ｱ') == 1


def test_mc_spacing_mark_is_one():
    # Devanagari vowel sign AA is Mc -> 1 column
    assert unicodedata.category('\u093e') == 'Mc'
    assert display_width('\u093e') == 1


def test_soft_hyphen_zero():
    assert display_width('a\u00adb') == 2


def test_cf_wide_or_not():
    # Cf takes priority: check any Cf char with W/F width gives 0
    for cp in range(0x110000):
        ch = chr(cp)
        if unicodedata.category(ch) == 'Cf':
            assert display_width(ch) == 0


def test_all_wide_chars_two():
    for cp in range(0x3000, 0xA000):
        ch = chr(cp)
        if unicodedata.category(ch) in ('Mn', 'Me', 'Cf'):
            continue
        if unicodedata.east_asian_width(ch) in ('W', 'F'):
            assert display_width(ch) == 2


def test_wide_combining_mark_zero():
    # Mn category with W width, if any, must be 0
    for cp in range(0x110000):
        ch = chr(cp)
        if unicodedata.category(ch) in ('Mn', 'Me') and unicodedata.east_asian_width(ch) in ('W', 'F'):
            assert display_width(ch) == 0


def test_mixed():
    assert display_width('a한\u0301b') == 4


def test_space_and_newline():
    assert display_width(' \n') == 2


def test_ambiguous_is_one():
    assert display_width('±') == 1
